        long nm = (long) n * m;
        long half = nm / 2;

        // DP[i][j] = min cost to process first i brackets with balance j
        // i ranges 0..nm, j ranges 0..half
        // Use two rows for space optimization
        int[][] dp = new int[2][(int) half + 1];
        for (int j = 0; j <= half; j++) dp[0][j] = INF;
        dp[0][0] = 0;

        int cur = 0, nxt = 1;
        for (int i = 0; i < nm; i++) {
            int ai = a[i % n];
            int bi = b[i % n];
            for (int j = 0; j <= half; j++) dp[nxt][j] = INF;
            for (int j = 0; j <= half; j++) {
                if (dp[cur][j] == INF) continue;
                // Place '('
                if (j + 1 <= half) {
                    dp[nxt][j + 1] = Math.min(dp[nxt][j + 1], dp[cur][j] + ai);
                }
                // Place ')'
                if (j > 0) {
                    dp[nxt][j - 1] = Math.min(dp[nxt][j - 1], dp[cur][j] + bi);
                }
            }
            cur ^= 1;
            nxt ^= 1;
        }

        System.out.println(dp[cur][0]);
    }

