                // open bracket
                if (bal + 1 <= n) {
                    long nc = cost + a[pos];
                    if (nc < next[(pos + 1) % n][bal + 1]) {
                        next[(pos + 1) % n][bal + 1] = nc;
                    }
                }
                // close bracket
                if (bal > 0) {
                    long nc = cost + b[pos];
                    if (nc < next[(pos + 1) % n][bal - 1]) {
                        next[(pos + 1) % n][bal - 1] = nc;
                    }
                }
            }
            dp = next;
        }

        System.out.println(dp[0][0]);
    }

    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        private int readByte() throws IOException {
            if (buflen == -1) return -1;
            if (ptr >= buflen) {
                buflen = in.read(buffer);
                ptr = 0;
                if (buflen <= 0) return -1;
            }
            return buffer[ptr++];
        }

        private boolean isSpace(int x) {
            return (x == ' ' || x == '\n' || x == '\r' || x == '\t' || x == -1);
        }

        private int nextInt() throws IOException {
            int c = readByte();
            while (c != -1 && isSpace(c)) c = readByte();
            int val = 0;
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            do {
                val = val * 10 + (c - '0');
                c = readByte();
            } while (c != -1 && !isSpace(c));
            return neg ? -val : val;
        }

        private long nextLong() throws IOException {
            int c = readByte();
            while (c != -1 && isSpace(c)) c = readByte();
            long val = 0;
            boolean neg = false;
            if (c == '-') {
                neg = true;
                c = readByte();
            }
            do {
                val = val * 10 + (c - '0');
                c = readByte();
            } while (c != -1 && !isSpace(c));
            return neg ? -val : val;
        }
    }
