        for (int i = 0; i < n; i++) {
            b[i] = Integer.parseInt(st.nextToken());
        }
        int[][] dp = new int[n][n + 1];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= n; j++) {
                dp[i][j] = Integer.MAX_VALUE / 2;
            }
        }
        dp[0][1] = a[0];
        for (int i = 1; i < n; i++) {
            for (int j = 0; j <= n; j++) {
                if (dp[i - 1][j] == Integer.MAX_VALUE / 2) continue;
                if (j + 1 <= n) {
                    dp[i][j + 1] = Math.min(dp[i][j + 1], dp[i - 1][j] + a[i]);
                }
                if (j > 0) {
                    dp[i][j - 1] = Math.min(dp[i][j - 1], dp[i - 1][j] + b[i]);
                }
            }
        }
        int minCycle = dp[n - 1][0];
        long total = (long) minCycle * m;
